css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .82); height: calc(var(--loader-size) * .84); display: flex; flex-direction: column; justify-content: space-between; }
.loader span { position: relative; height: 30%; border-radius: 50% / 26%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 26%, var(--accent))); animation: query calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 36%; border-radius: 50%; background: color-mix(in srgb, #fff 28%, var(--accent-2)); }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .4); }
@keyframes query { 0%, 100% { box-shadow: 0 0 0 0 transparent; filter: brightness(1); } 45% { box-shadow: 0 0 calc(var(--loader-size) * .08) var(--accent-2); filter: brightness(1.22); } }
